fn choose_num(x: i8, y: i8) -> i8 {
    // Invalid interval
    if x > y {
        return -1;
    }

    // The largest even number in [x, y] is:
    // - y, if y is even
    // - y - 1, if y is odd
    let candidate = if y % 2 == 0 { y } else { y - 1 };

    // If candidate drops below x, then there is no even number in the interval
    if candidate < x {
        -1
    } else {
        candidate
    }
}

